/**
 * Local ADEME Base Empreinte® / Base Carbone® V23.11 index.
 *
 * Generated by scripts/generate-base-carbone-index.ps1 from the official
 * CP1252/semicolon CSV export (Base_Carbone_V23.11.csv, June 2026). Do not edit
 * the generated JSON by hand.
 *
 * This frozen index is the SINGLE source of truth for carbon factors: there is
 * no online fallback and no mixed-version lookup. Keeping the reference data
 * local makes carbon calculations reproducible, offline and auditable: every
 * factor is traceable to an ADEME id, version, unit, uncertainty and source.
 */
import rawIndex from './baseCarboneV2311.generated.json' with { type: 'json' };

/** [id, name, attribute, category, unit, value, geo, subGeo, uncertainty, program, validity, source] */
export type FactorTuple = [
  string,
  string,
  string,
  string,
  string,
  number,
  string,
  string,
  number | null,
  string,
  string,
  string,
];

export interface LocalFactor {
  id: string;
  name: string;
  attribute: string;
  category: string;
  unit: string;
  value: number;
  geography: string;
  subGeography: string;
  uncertaintyPct: number | null;
  program: string;
  validity: string;
  source: string;
  version: string;
}

export const BASE_CARBONE_VERSION = rawIndex.version;
export const BASE_CARBONE_SOURCE_SHA256 = rawIndex.sourceSha256;
export const BASE_CARBONE_SOURCE_FILE = rawIndex.sourceFile;
export const BASE_CARBONE_GENERATED_AT = rawIndex.generatedAt;

/** Unicode-normalised text used for deterministic matching. */
export function normalizeText(input: string): string {
  return (input || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ');
}

interface IndexedFactor extends LocalFactor {
  searchName: string;
  searchAttribute: string;
  searchCategory: string;
  searchProgram: string;
  searchUnit: string;
  tokens: string[];
}

const index: IndexedFactor[] = (rawIndex.factors as FactorTuple[]).map((f) => {
  const factor: LocalFactor = {
    id: f[0],
    name: f[1],
    attribute: f[2],
    category: f[3],
    unit: f[4],
    value: f[5],
    geography: f[6],
    subGeography: f[7],
    uncertaintyPct: f[8],
    program: f[9],
    validity: f[10],
    source: f[11],
    version: rawIndex.version,
  };

  const searchName = normalizeText(factor.name);
  const searchAttribute = normalizeText(factor.attribute);
  const searchCategory = normalizeText(factor.category);
  const searchProgram = normalizeText(factor.program);
  const searchUnit = normalizeText(factor.unit);

  return {
    ...factor,
    searchName,
    searchAttribute,
    searchCategory,
    searchProgram,
    searchUnit,
    tokens: Array.from(new Set(`${searchName} ${searchAttribute}`.split(' ').filter((t) => t.length > 1))),
  };
});

/**
 * Inverse document frequency: generic tokens ("de", "transport") must not
 * outweigh distinctive ones ("routier", "ferroviaire", "pehd"). Computed once
 * from the frozen index, so scoring stays deterministic and offline.
 */
const tokenDocumentFrequency = new Map<string, number>();
for (const f of index) {
  for (const token of f.tokens) {
    tokenDocumentFrequency.set(token, (tokenDocumentFrequency.get(token) || 0) + 1);
  }
}
const idf = (token: string): number =>
  1 + Math.log(index.length / (1 + (tokenDocumentFrequency.get(token) || 0)));

export function getIndexStats() {
  return {
    version: BASE_CARBONE_VERSION,
    sourceFile: BASE_CARBONE_SOURCE_FILE,
    sourceSha256: BASE_CARBONE_SOURCE_SHA256,
    generatedAt: BASE_CARBONE_GENERATED_AT,
    factorCount: index.length,
    offline: true,
  };
}

export function getFactorById(id: string): LocalFactor | undefined {
  return index.find((f) => f.id === id);
}

export function searchLocalFactors(
  query: string,
  options: { size?: number; unitHint?: string; categoryHint?: string; allowNegative?: boolean } = {}
): Array<LocalFactor & { matchScore: number }> {
  const searchQuery = normalizeText(query);
  if (!searchQuery) return [];

  const queryTokens = searchQuery.split(' ').filter((t) => t.length > 1);
  if (queryTokens.length === 0) return [];

  const unitHint = normalizeText(options.unitHint || '');
  const categoryHint = normalizeText(options.categoryHint || '');
  const size = Math.min(50, Math.max(1, options.size ?? 8));

  const totalIdf = queryTokens.reduce((sum, token) => sum + idf(token), 0) || 1;
  const weightedHits = (text: string): number =>
    queryTokens.reduce((sum, token) => sum + (text.includes(token) ? idf(token) : 0), 0) / totalIdf;

  const scored: Array<LocalFactor & { matchScore: number }> = [];

  for (const f of index) {
    if (!options.allowNegative && f.value < 0) continue;
    // 1,645 rows are activity data (%, kWh/m2.an, GWh...), not emission factors.
    // Only kgCO2e-based rows may feed a carbon calculation.
    if (!f.searchUnit.includes('co2e')) continue;

    let score = 0;
    if (f.searchName === searchQuery) score += 120;
    else if (f.searchName.includes(searchQuery)) score += 80;
    if (f.searchAttribute && f.searchAttribute.includes(searchQuery)) score += 60;

    // A full phrase in the ADEME category path is the strongest disambiguator:
    // "Transport de marchandises > Routier" beats "Train de marchandises".
    if (f.searchCategory.includes(searchQuery)) score += 95;
    const fullHaystack = `${f.searchName} ${f.searchAttribute} ${f.searchCategory} ${f.searchProgram} ${f.searchUnit}`;
    if (fullHaystack.includes(searchQuery)) score += 40;

    score += weightedHits(f.searchName) * 60;
    score += weightedHits(f.searchAttribute) * 25;
    score += weightedHits(f.searchCategory) * 35;

    if (unitHint && f.searchUnit.includes(unitHint)) score += 20;
    if (categoryHint && f.searchCategory.includes(categoryHint)) score += 15;

    // Prefer documented, recent factors when relevance is otherwise equal.
    if (f.uncertaintyPct !== null && f.uncertaintyPct <= 30) score += 5;
    if (f.program) score += 2;

    if (score > 0) {
      scored.push({
        id: f.id,
        name: f.name,
        attribute: f.attribute,
        category: f.category,
        unit: f.unit,
        value: f.value,
        geography: f.geography,
        subGeography: f.subGeography,
        uncertaintyPct: f.uncertaintyPct,
        program: f.program,
        validity: f.validity,
        source: f.source,
        version: f.version,
        matchScore: Math.round(score * 10) / 10,
      });
    }
  }

  scored.sort((a, b) => b.matchScore - a.matchScore || a.name.localeCompare(b.name));
  return scored.slice(0, size);
}

/**
 * Converts an activity quantity into the reference quantity of a factor unit.
 * Example: 500 kg of a product -> 0.5 tonne for a `kgCO2e/tonne` factor.
 */
export function convertActivityQuantity(
  quantity: number,
  fromUnit: string,
  factorUnit: string
): number | null {
  // ADEME units look like "kgCO2e/tonne": strip the numerator before
  // inspecting the denominator, otherwise every factor looks like a "kg".
  const denominator = (u: string): string => u.replace(/^kgco2e\s*/, '').trim();
  const from = denominator(normalizeText(fromUnit));
  const to = denominator(normalizeText(factorUnit));

  const kgPer = (u: string): number | null => {
    if (u.includes('tonne')) return 1000;
    if (u.startsWith('kg') || u.includes(' kg')) return 1;
    if (u === 't') return 1000;
    // "t km" is a tonne-kilometre, not a plain tonne: refuse the ambiguity.
    return null;
  };

  // Same unit family: no conversion needed.
  if (from === to) return quantity;

  const fromKg = kgPer(from);
  const toKg = kgPer(to);
  if (fromKg !== null && toKg !== null) {
    return (quantity * fromKg) / toKg;
  }

  // Energy units.
  if (from.includes('mwh') && to.includes('kwh')) return quantity * 1000;
  if (from.includes('kwh') && to.includes('mwh')) return quantity / 1000;

  return null;
}

/** Computes kg CO2e from an activity amount and a local ADEME factor. */
export function computeFactorEmissions(params: {
  factor: LocalFactor;
  quantity: number;
  activityUnit?: string;
}): number | null {
  if (!Number.isFinite(params.quantity)) return null;
  const qty = params.activityUnit
    ? convertActivityQuantity(params.quantity, params.activityUnit, params.factor.unit)
    : params.quantity;
  if (qty === null) return null;
  const result = qty * params.factor.value;
  return Number.isFinite(result) ? Math.round(result * 1000) / 1000 : null;
}
